#!/usr/bin/env python3
"""Post-experiment R11 tables and Chinese report; never generates models."""
import json,csv,statistics as st
from pathlib import Path
ROOT=Path(__file__).resolve().parents[1];BASE=ROOT/'results/round11_projection';C=BASE/'main_10s';B=BASE/'mechanism';MODES=['plain_only','plain_extra','projection_fixed']
def lines(p):return [json.loads(x) for x in p.read_text().splitlines()]
def read(p):return list(csv.DictReader(p.open()))
def short(case):return 'Bromberger' if 'Bromberger' in case else 'SMT_random' if 'SMT_random' in case else 'convert'
def avg(rows,k):return st.mean(float(r[k]) for r in rows)
def write(p,rows):
 with p.open('w') as f:
  w=csv.DictWriter(f,fieldnames=list(rows[0]));w.writeheader();w.writerows(rows)
def main():
 rows=read(C/'sessions.csv');cases=sorted({r['instance'] for r in rows});pairs=read(C/'paired_summary.csv');queries=read(C/'queries.csv');decision=json.loads((C/'decision.json').read_text());plan=json.loads((C/'plan.json').read_text());assert not decision['enter_D'] and not decision['propose_30s_only']
 mechanism=[];mq=[]
 for r in lines(B/'runs.jsonl'):
  d=B/r['output'];s=r['summary'];qs=lines(d/'queries.jsonl');cc=lines(d/'candidates.jsonl');cost={c['action']:c['seconds'] for c in lines(d/'phase_costs.jsonl')}
  row=dict(instance=r['instance'],process_seconds=r['process_seconds'],**s);row['internal_duplicates']=sum(c['internal_duplicate'] for c in cc);row['formal_duplicates']=sum(c['formal_duplicate'] for c in cc);row['max_phase_seconds']=max(cost.values(),default=0);row['stage_overruns']=sum(cost[q['action']]>q['allowance'] for q in qs);mechanism.append(row)
  for q in qs:mq.append(dict(instance=r['instance'],mode=r['mode'],seed=r['seed'],action=q['action'],status=q['status'],phase_seconds=cost[q['action']],allowance=q['allowance'],query_seconds=q['query_seconds'],**q['evidence'],blocks_after=(q['condition'] or {}).get('blocks_after'),block_seconds=(q['condition'] or {}).get('block_seconds'),checkpoint_completed=q['checkpoint_completed'],timely=q['timely'],gain=q['gain']))
 write(B/'sessions.csv',mechanism);write(B/'queries.csv',mq)
 accounting=[]
 for run in lines(C/'runs.jsonl'):
  raw=C/run['output'];cycles=lines(raw/'cycles.jsonl');extras=lines(raw/'extra.jsonl');ss=run['summary']
  accounting.append(dict(id=run['id'],instance=run['instance'],seed=run['seed'],mode=run['mode'],potential_triggers=ss['triggers'],extra_stages=len(extras),actual_extra_checks=sum(q['evidence']['check_started'] for q in lines(raw/'queries.jsonl') if q['origin']!='plain'),quota_or_delivery_skips=sum(c['extra_status']=='extra_quota_or_delivery_reserve' for c in cycles),block_cap_skips=sum(c['extra_status']=='projection_block_cap' for c in cycles),final_block_count=ss['projection_blocks'],block_stop_reason=ss['projection_stop_reason'],session_stop_reason=ss['terminal'],extra_max_stage_seconds=max((c['extra_seconds'] for c in cycles),default=0),extra_full_seconds=ss['extra_spent'],extra_quota_seconds=ss['extra_quota'],initialization_seconds=ss['guided_initialization_seconds'],feedback_seconds=ss['feedback_seconds'],cleanup_seconds=ss['guided_cleanup_seconds']))
 write(C/'mechanism_accounting.csv',accounting)
 text=['# 第十一轮：投影去重和查询机会修补报告','','**验收结论：修补有效，性能未通过，停止扩大实验。** Bromberger 的投影内部重复降为零，convert 真正进入求解并产生了不同合法正收益候选；SMT_random 实际获得 200 ms 后仍全部 Unknown。前两项机制修补没有转化为跨实例可重复的累计覆盖改善。未提出或执行 30 秒验证，未运行 900 秒或 HighDiv。','','## 范围与冻结','','基于 `833bca1`，新分支 `round11-projection-fix`；实验代码/协议冻结提交 `'+plan['commit']+'`。第十轮报告、全部原始结果和旧 projection_online_probe 入口保持不变。共享类以选项开启修补：旧默认仍为无持久投影阻塞、50 ms 查询，新入口 projection_fixed_probe 使用完整阻塞和200ms请求。Global::explore 只增加默认关闭的请求时限覆盖参数，用于让 plain_extra 也确实请求200ms，不改变原普通探索策略。','','本轮两个修补分别是：','','- SAT 完成所有原变量补全、验证完整 F 后，先 pop 临时投影条件，再在常驻引导 solver 添加完整赋值的精确 no-good，并记录身份。不论候选是否胜出或是否及时输出都登记；不阻塞整个投影类别，不把带阻塞的 UNSAT 当作 F 无解。最多256条，达到上限停止后续投影，不清空重建。','- 两个额外配置阶段上限250ms、check请求上限200ms、每次最多一次check；完整阶段包括懒初始化、反馈、构造、求解、补全、验证、阻塞和候选日志。阶段内预留20ms，最终交付另留50ms；会话额外总额仍为10%，预留5ms维护余量、不启动不足40ms阶段。普通优先、初始互补、连续4零收益与4次普通机会冷却完全沿用。','','仍按同一 S 的真实 AST covered/observed 竞争；重复、失败或较差投影不丢失及时普通见证。只有正式写完且截止检查通过后才更新正式覆盖。完整 seen0/seen1、短路访问、整数低64位和原分母不变。内部去重与正式去重集合分开，未输出候选不计正式覆盖。','','## 旧现象复核与回归','','只读核对第十轮带哈希原始日志：Bromberger 730次投影SAT中51个新候选、656次内部重复、23次正式重复；SMT_random 21次原始 Unknown/canceled，实际授予7–34ms、纯check约7.21–34.29ms；convert solver初始化52.69/47.19/42.31ms，三会话均无投影check。证据另存 round10_recheck.json，没有重跑旧实验。','','Release、ASan/UBSan 均通过 **17项 C++ +112项 Python** 回归，包含原16/104项。新增测试覆盖：跨pop的持久完整阻塞、同投影其他赋值仍可用、256上限后的普通回退、重复防护、Bool/大整数、Unknown/取消/父预算截短、模拟已耗60ms准备后实际进入check、两条额外路径都获得200ms请求、及时普通见证保留、冻结Manual差分和禁止自动长跑。保留leak检测及已冻结外部Z3抑制项。','','## 小型机制验证','','三个原开发公式prefix-1、seed0，两个组件配置各0.75秒、最多16次动作，共6会话同批运行。初始化和恢复计入0.75秒。组件直接调用模块、固定S和历史不提交新模型，目的是检查阻塞与实际check；这不是10%额外配额下的在线轨迹，也不能把各候选针对固定S的收益相加作为联合覆盖。','','| 案例 / 模式 | 实际check | SAT | 及时不同候选 | 正收益候选 | solver初始化ms | 进程秒 |','|---|---:|---:|---:|---:|---:|---:|']
 for r in sorted(mechanism,key=lambda r:(r['instance'],r['mode'])):text.append(f"| {short(r['instance'])} / {r['mode']} | {r['checks']} | {r['sat']} | {r['timely_distinct']} | {r['positive']} | {1000*r['initialization_seconds']:.3f} | {r['process_seconds']:.4f} |")
 text+=['','Bromberger 两配置都返回16个不同正收益候选，新投影没有内部/正式重复。SMT_random 两方均4次Unknown，投影前三次授予200ms，尾次受总预算截短至47ms，未补发时间。convert 投影初始化47.31ms后实际进入check，第一次授予164ms，9.41ms返回合法见证；其余失败查询及成本全部保留。六会话独立Manual审计通过，验证46次模型求值；组件阶段超限 '+str(sum(r['stage_overruns'] for r in mechanism))+' 次。','','## 18个10秒在线配对会话','','仅原三个开发公式prefix-1、seed0/1、plain_only/plain_extra/projection_fixed，共18会话，每批两个完整配置组、最多六路同步、按seed轮换顺序。采样后才审计，无构建/审计并行干扰。会话是配对单位，只有两个seed，不宣称统计显著性。原第十轮只作历史机制参考。','','独立Manual审计通过 **13101次模型求值**，所有完整覆盖状态、候选边际、去重、及时输出和边际累计恒等式一致。输入和归档审计核验原prefix/seed、同状态同波次及216个原始成员哈希。18会话全部完成，没有删除失败/零输出。阶段实际成本最大226.08ms，每会话全部额外成本均小于1秒；阶段和会话额度超限均为0。同步原生操作仍不是一般意义上的硬实时保证，本批只报告实际观测。','','累计新增bit的逐seed结果：','','| 案例 | seed | plain_only | plain_extra | projection_fixed | fixed − extra | fixed − only |','|---|---:|---:|---:|---:|---:|---:|']
 for case in cases:
  for seed in ('0','1'):
   vals={r['mode']:int(r['gain']) for r in rows if r['instance']==case and r['seed']==seed};text.append(f"| {short(case)} | {seed} | {vals['plain_only']} | {vals['plain_extra']} | {vals['projection_fixed']} | {vals['projection_fixed']-vals['plain_extra']:+d} | {vals['projection_fixed']-vals['plain_only']:+d} |")
 text+=['','均值（两个seed的中位数与均值相同），括号为原分母的覆盖率增量百分点：','','| 案例 | plain_only | plain_extra | projection_fixed |','|---|---:|---:|---:|']
 for case in cases:
  text.append('| '+short(case)+' | '+' | '.join(f"{avg([r for r in rows if r['instance']==case and r['mode']==m],'gain'):.2f}（{avg([r for r in rows if r['instance']==case and r['mode']==m],'gain_percentage_points'):.3f} pp）" for m in MODES)+' |')
 text+=['','| 案例 | fixed vs extra 胜/平/负 | fixed vs only 胜/平/负 | extra vs only 胜/平/负 |','|---|---|---|---|']
 for case in cases:
  by={r['contrast']:r for r in pairs if r['instance']==case};text.append('| '+short(case)+' | '+' | '.join(f"{by[k]['win']}/{by[k]['tie']}/{by[k]['loss']}" for k in ('projection_fixed - plain_extra','projection_fixed - plain_only','plain_extra - plain_only'))+' |')
 text+=['','![10秒累计覆盖](../results/round11_projection/main_10s/figures/coverage_curves.png)','','曲线为两个seed均值，阴影是范围，不是置信区间。','','## 三个修补问题的直接答案','','**Bromberger：去重修补生效，覆盖表现没有改善。** 292次投影SAT得到292个首次不同合法候选，内部重复0、正式重复0；77次严格胜过同周期普通候选，正增益投影候选79次，净替换差合计550bit。每会话持久阻塞为123/169条，未达到256；256后停止已由回归验证。全部阻塞构造/登记合计41.22ms，计入约1.918秒完整额外成本。相较旧报告的679/730重复，这是身份去重的直接修补证据，不能当作不同轮次的同负载性能对照。','','然而两个seed的最终覆盖都输给两个本轮对照：fixed平均910.5bit，extra969.5，only1116.5。固定S中的净替换差550不能直接加到端到端覆盖上，正式模型、后续普通求解历史及机会成本已改变。fixed的最长连续零收益输出均值444.5，only144.5；最长无增长时间均值3.747秒，only2.305秒。新模型更多没有消除覆盖重复。','','**SMT_random：求解时限真实增加，但没有及时投影模型。** 在线四次投影check均实际授予200ms，没有被父预算截短，纯check分别200.163、200.114、200.105、200.112ms。原始结果全部Unknown，reason为canceled，控制层按时间证据标记suspected_local_timeout/inferred；不作不可达判断。两个会话分别消耗额外0.2265/0.6297秒，没有SAT、没有正收益候选。','','fixed累计覆盖相对extra两seed都更高，均值也略高于only，但其正式输出全部来自普通探索，不能归功于投影。尤其extra/seed0在普通探索阶段一直没有SAT，额外查询数为0；不能把这次零输出解释为额外200ms查询拖慢，也不能将它当成投影有效的证据。未验证的原始序列差异不统称随机噪声。本轮没有针对这些差异做额外求解或因果消融。','','**convert：终于执行投影并返回SAT，但候选不值得替换普通见证。** 两会话初始化43.94/44.71ms，投影实际授予170/171ms，纯check9.92/84.93ms；两份候选都不同、合法、及时，对冻结S新增5821/6092bit。同期普通候选却新增33573/33705bit，因此两次均保留普通候选，投影严格赢家为0、正式投影输出为0。完整额外成本82.73/159.18ms（含清理）。一seed最终赢、另一seed明显输；平均较extra少2.5bit、较only少2138bit，没有净收益通过。','','## 逐会话供给、成本与高原','','不同合法候选数包含截止前验证完成但未输出的候选，正式覆盖只计已提交模型。普通SAT与额外SAT都保留，不通过删除零收益模型美化比例。进程墙钟含初始化和析构。以下新数是全部来源的首次不同合法候选数；extra列为额外查询/check调用数，本批调用均实际进入check。','','| 案例 / seed / 模式 | 进程秒 | 普通SAT | extra | 新候选数 | 正式数 | 全部额外秒 | 最长高原秒 |','|---|---:|---:|---:|---:|---:|---:|---:|']
 for r in sorted(rows,key=lambda r:(r['instance'],r['seed'],MODES.index(r['mode']))):text.append(f"| {short(r['instance'])} / {r['seed']} / {r['mode']} | {float(r['process_seconds']):.4f} | {r['plain_sat']} | {r['extra_calls']} | {r['unique_validated_candidates']} | {r['outputs']} | {float(r['extra_spent']):.4f} | {float(r['longest_plateau_seconds']):.4f} |")
 text+=['','投影候选的逐seed机制指标：','','| 案例 / seed | 投影SAT | 新投影候选 | 内部/正式重复 | 正增益候选 | 严格赢家 | 纯check秒 | 阻塞成本ms |','|---|---:|---:|---|---:|---:|---:|---:|']
 for r in rows:
  if r['mode']!='projection_fixed':continue
  text.append(f"| {short(r['instance'])} / {r['seed']} | {r['extra_sat']} | {r['projection_new_candidates']} | {r['projection_internal_duplicates']} / {r['projection_formal_duplicates']} | {r['projection_positive_candidates']} | {r['projection_positive_strict_winners']} | {float(r['projection_check_seconds']):.6f} | {1000*float(r['projection_block_seconds']):.3f} |")
 text+=['','普通阶段可用墙钟均值（only/extra/fixed）：Bromberger为9.023/8.166/7.848秒；SMT_random为9.313/9.329/9.365秒；convert为9.725/9.588/9.663秒。它不是全部成本，正式输出、初始化等另计，不能与包含它的进程成本重复相加。固定10%额度只限制额外开销，不能保证SAT产量：SMT_random的fixed候选供给只有only的19.67%、extra的41.55%；convert为only的52.36%。Bromberger虽供给为only的135.06%，仍更少新增覆盖。供给保护未通过。','','查询账本 queries.csv 逐条给出原始status/reason、请求/授予ms、pure check、构造/补全/验证、父预算余额及截短原因、完整阻塞时间与前后数量。mechanism_accounting.csv 汇总实际check、额度/交付预留跳过、256上限跳过、会话退出原因及清理成本；本批没有达到256上限。Bromberger的292次投影有62次受剩余阶段/额外额度截短（实际21–200ms），未重新领取完整时限。SMT_random在线四次均无截短；convert两次因初始化与准备扣除而截短至170/171ms。全额成本来自extra_spent，包含失败和准备，查询分项与整阶段有包含关系。阻塞本身属于查询总成本，不重复相加。','','## 前缀覆盖和未完成状态','','以下是前1/2/5/10个新正式样本的累计新增bit；“—”为未达到，不补零、不删会话。','','| 案例 / seed / 模式 | 前1 | 前2 | 前5 | 前10 |','|---|---:|---:|---:|---:|']
 for r in sorted(rows,key=lambda r:(r['instance'],r['seed'],MODES.index(r['mode']))):text.append('| '+short(r['instance'])+' / '+r['seed']+' / '+r['mode']+' | '+' | '.join(r[f'prefix_{n}'] or '—' for n in (1,2,5,10))+' |')
 text+=['','Bromberger前缀与only相同，首个输出弱于extra；convert/fixed/seed1只完成1份，第二份及后续前缀未达到；SMT_random/extra/seed0全部前缀未达到。按事前“两seed同时超过10%退步”的规则，没有触发可重复早期退步项，但这不表示每条轨迹均无退步。','','## 验收决定与限制','','本轮结论为 **修补有效、性能未通过**：去重和初始化机会问题解决，但SMT_random仍无投影SAT，convert的两份投影均输给已拥有的普通模型，Bromberger更多互补候选也未带来同预算最终优势。满足事前“两个seed都胜过两个对照且有严格投影赢家”的独立公式数为0，候选供给保护也失败。decision.json为STOP_performance_not_passed，propose_30s_only=false、enter_D=false。不提新参数，不扩大实验，不用更多预算追正例。','','两项修补同时启用，本轮不能区分它们各自对端到端轨迹的独立因果效果。可以确认的是：持久阻塞的作用域、真实授予时间和合法候选身份都有直接证据；最终指标仍不支持继续。只有2个seed、3个开发公式，不外推到全部数据集，不声称新的生成理论或算法优势。','','## 文件与可重放命令','','代码：include/feedback_projection.hpp、src/feedback_projection.cpp、src/projection_fixed_probe.cpp；Global::explore新增默认关闭的时限请求参数。src/projection_component_probe.cpp仅用于固定状态组件验证。协议在 docs/第十一轮实验协议.md，原第十轮结果未修改。','','```bash','cmake -S . -B build/round11/release -DCMAKE_BUILD_TYPE=Release -DZ3_PREFIX=/tmp/lia-highdiv-frozen/venv','cmake --build build/round11/release -j6','bash scripts/test_projection_fix_build.sh release','cmake -S . -B build/round11/sanitize -DCMAKE_BUILD_TYPE=Debug -DZ3_PREFIX=/tmp/lia-highdiv-frozen/venv \\\n  -DCMAKE_CXX_FLAGS="-O1 -g -fsanitize=address,undefined -fno-omit-frame-pointer" \\\n  -DCMAKE_EXE_LINKER_FLAGS="-fsanitize=address,undefined"','cmake --build build/round11/sanitize -j6','bash scripts/test_projection_fix_build.sh sanitize','```','','原实验完整命令逐会话存于 runs.jsonl。新目录重放（代码须为clean tracked状态；不覆盖归档）：','','```bash','export HIGHDIV_ROOT=/tmp/lia-highdiv-frozen','PY=/tmp/lia-highdiv-frozen/venv/bin/python3','$PY scripts/run_projection_fix.py --stage B --binary build/round11/release/projection_component_probe --output /tmp/r11-component-replay','$PY scripts/audit_projection_component.py /tmp/r11-component-replay --jobs 6','$PY scripts/run_projection_fix.py --stage C --binary build/round11/release/projection_fixed_probe --output /tmp/r11-online-replay','$PY scripts/audit_projection_fix.py /tmp/r11-online-replay --jobs 6','$PY scripts/audit_projection_fix_inputs.py /tmp/r11-online-replay','$PY scripts/analyze_projection_fix.py /tmp/r11-online-replay','```','','C入口还要求仓库本次组件AUDIT通过；不含D入口。只复核保存证据时不运行run脚本，先解压raw.tar.gz到对应批次目录，或在副本运行审计以避免覆盖既有audit/。审计调用被no_search限制，只对原模型具体求值。单会话入口：','','```bash','build/round11/release/projection_fixed_probe benchmarks/SMT_random_LIA_ex14600_2600_100.smt2 \\\n  projection_fixed 10 0 /tmp/r11-single \\\n  results/round3_snapshots/states/SMT_random_LIA_ex14600_2600_100.smt2/prefix-1/prefix.values \\\n  results/round3_snapshots/states/SMT_random_LIA_ex14600_2600_100.smt2/prefix-1/seed.values','```','','将模式换为plain_only/plain_extra并使用新的输出目录即可。results/round11_projection下保存完整原始模型与日志归档、逐成员哈希、逐会话审计、每查询成本、sessions/curves/costs/pairs/summary/paired_summary表、门槛和可导出图。CSV均保留零输出/失败；全部模型身份绑定来源与时间。冻结源码摘要：`'+plan['source_sha256']+'`。']
